import React from 'react';
import UnityGame from "../UnityGame";
import Project from "../Project";

const MergyDergy: React.FC = () => {
  return (
    <Project
      thumbnail="/Mergy Dergy/thumbnail.png"
      thumbnailGif="/Mergy Dergy/preview.gif"
      title="Mergy Dergy"
      tech={["C#", "Unity"]}
      date={"2024"}
      platforms={["PC", "Web", "Android"]}
      description="A Suika game clone with some QOL enhancements, play advocacy features, and some alternate physics pack with an audio experience."
      contributions={"I developed everything from scratch."}
      playable={true}
      section="2D Projects"
      offset={"middle"}
    >
      <p><b>Goal:</b></p>
      <p>Merge 2 level 10 circle or score higher points than your friends!</p>
      <p>Get same level circles to touch to merge them into a bigger circle.</p>
      <p><b>Controls:</b></p>
      <p>Left Click to drop</p>
      <p>Right Click to Aim</p>

      <UnityGame src={"/Mergy Dergy/index.html"} title={"Mergy Dergy"} height={2100} width={900}/>
    </Project>
  );
}

export default MergyDergy;