import React from 'react';
import styled from 'styled-components';
import Project from "../Project";

const FeatureContainer = styled.div`
margin-top: 20px;
`;

const FeatureList = styled.ul`
list-style-type: none;
padding: 0;
`;

const FeatureItem = styled.li`
margin-bottom: 20px;
`;

const FeatureTitle = styled.h4`
margin-bottom: 5px;
color: #ffffff;
text-decoration: underline;
`;

const FeatureImage = styled.img`
max-width: 100%;
margin-top: 10px;
border: 1px solid #ddd;
border-radius: 4px;
`;

const SectionHeader = styled.h3`
color: #9c27b0;
text-shadow: 1px 1px 1px #000000;
`;

const GameEngine: React.FC = () => {

  const gameplayFeatures = [
    { feature: "Snake Game", image: "/GameEngine/SnakeGame.gif", description: "Classic Snake game with head, body growth, collisions, and wall detection." },
    { feature: "Shooter Game", image: "/GameEngine/ShooterGame.gif", description: "Top-down shooter with enemies, projectiles, and collision-based combat." },
  ];

  const technicalFeatures = [
    { feature: "Camera System", image: "", description: "Camera follows player and smoothly rotates relative to the target." },
    { feature: "Input System", image: "", description: "Abstract input handling with key states and mouse-to-world conversion." },
    { feature: "Rendering Pipeline", image: "", description: "Depth-based render order with camera-relative position and rotation calculations." },
    { feature: "Object Lifecycle", image: "", description: "Deferred addition and removal of objects during update cycles." },
  ];

  const tools = [
    { name: "Shape Abstraction (SFML backend)", image: [] },
    { name: "Reusable Math Library", image: [] },
  ];

  return (
    <Project
      thumbnail={"/GameEngine/thumbnail.png"}
      thumbnailGif="/GameEngine/preview.gif"
      title="2D Game Engine"
      date={"2020"}
      tech={["C++"]}
      platforms={["PC"]}
      description="A modular C++ 2D game engine developed from scratch to support custom rendering, input, and gameplay systems. Includes two gameplay demos (Snake and Shooter) and abstract backend design for future portability."
      contributions={"I developed the engine and all sample games solo."}
      section="2D Projects"
    >

      <FeatureContainer>
        <SectionHeader>Project Overview:</SectionHeader>
        <p>
          A modular C++ 2D game engine created to build and experiment with engine architecture, game loops, rendering abstraction,
          input handling, and gameplay implementation. Supports clean, reusable systems for building diverse games using custom logic.
        </p>
        <p>
          Example games (Snake and Shooter) demonstrate flexibility and performance in player interaction, AI enemies, projectiles,
          and world interaction.
        </p>
      </FeatureContainer>

      <SectionHeader>Gameplay Features:</SectionHeader>
      <FeatureList>
        {gameplayFeatures.map((feature, index) => (
          <FeatureItem key={index}>
            <FeatureTitle>{feature.feature}</FeatureTitle>
            <FeatureImage src={feature.image} alt={feature.feature} />
            <p>{feature.description}</p>
          </FeatureItem>
        ))}
      </FeatureList>

      <SectionHeader>Technical Systems:</SectionHeader>
      <FeatureList>
        {technicalFeatures.map((feature, index) => (
          <FeatureItem key={index}>
            <FeatureTitle>{feature.feature}</FeatureTitle>
            {feature.image && <FeatureImage src={feature.image} alt={feature.feature} />}
            <p>{feature.description}</p>
          </FeatureItem>
        ))}
      </FeatureList>

      <FeatureContainer>
        <SectionHeader>Tools and Modules:</SectionHeader>
        <FeatureList>
          {tools.map((tool, index) => (
            <FeatureItem key={index}>
              <FeatureTitle>{tool.name}</FeatureTitle>
              {tool.image.map((image, index) => (
                <FeatureImage src={image} />
              ))}
            </FeatureItem>
          ))}
        </FeatureList>
      </FeatureContainer>
    </Project>
  );
};

export default GameEngine;
