import React from 'react';
import styled from 'styled-components';
import Project from "../Project";

const FeatureContainer = styled.div`
    margin-top: 20px;
`;

const FeatureList = styled.ul`
    list-style-type: none;
    padding: 0;
`;

const FeatureItem = styled.li`
    margin-bottom: 20px;
`;

const FeatureTitle = styled.h4`
    margin-bottom: 5px;
    color: #ffffff;
    text-decoration: underline;
`;

const FeatureImage = styled.img`
    max-width: 100%;
    margin-top: 10px;
    border: 1px solid #ddd;
    border-radius: 4px;
`;

const SectionHeader = styled.h3`
    color: #9c27b0;
    text-shadow: 1px 1px 1px #000000;
`;

const InterstellarDefenseEngineer: React.FC = () => {
  const unityFeatures = [
    {feature: 'Modular Tower Creation', image: '/InterstellarDefenseEngineer/Unity_TowerCreation.gif', description: 'Design towers with customizable weapons, firing behaviors, color regions, and targeting rules.'},
    {feature: 'Predictive Targeting and Combat', image: '/InterstellarDefenseEngineer/Unity_PredictiveTargeting.gif', description: 'Use advanced math to predict enemy movement and optimize projectile firing.'},
    {feature: 'Performance Optimization', image: '/InterstellarDefenseEngineer/Unity_Optimization.gif', description: 'Object pooling and DOTS experiments to handle massive battles efficiently.'},
    {feature: 'Integrated 3D UI', image: '/InterstellarDefenseEngineer/Unity_UI.gif', description: 'State-based camera transitions and 3D UI elements for intuitive creation and battle modes.'},
  ];

  const unrealFeatures = [
    {feature: 'Reusable Gameplay Components', image: '/InterstellarDefenseEngineer/Unreal_ActorComponents.png', description: 'Built modular Actor Components in UE5 for targeting, movement, damage, and procedural behaviors.'},
    {feature: 'Advanced Damage and Shield Systems', image: '/InterstellarDefenseEngineer/Unreal_DamageSystems.gif', description: 'Damage over time, shields, resistances, and piercing attacks implemented with clean, reusable components.'},
    {feature: 'Projectile and Tower Augmentation Systems', image: '/InterstellarDefenseEngineer/Unreal_Projectiles.gif', description: 'Runtime augmentations and slotting system for dynamic tower weapon loadouts.'},
    {feature: 'Blueprint Visual Presentation', image: '/InterstellarDefenseEngineer/Unreal_UIBlueprints.gif', description: 'Floating damage numbers, health bars, and path visualization created with Blueprint and hooked into C++ logic.'},
  ];

  return (
    <Project
      thumbnail={"/InterstellarDefenseEngineer/thumbnail.png"}
      thumbnailGif="/InterstellarDefenseEngineer/preview.gif"
      title="Interstellar Defense Engineer"
      date={"2023"}
      tech={["C#", "Unity", "Unreal Engine 5 (C++ + Blueprint)"]}
      platforms={["PC"]}
      description="A highly modular tower defense game emphasizing player customization, advanced targeting systems, and scalable, designer-friendly architecture. Developed first in Unity and later partially prototyped in Unreal Engine 5 to explore next-gen modular gameplay frameworks."
      contributions={"Solo developer responsible for all gameplay systems, UI, asset integration, tools, and technical design."}
      section="3D Projects"
    >
      <FeatureContainer>
        <SectionHeader>Project Overview:</SectionHeader>
        <p>
          Interstellar Defense Engineer was designed to push the boundaries of player-driven tower defense,
          allowing players to customize every part of their towers while maintaining scalability and performance.
          Built first in Unity and later explored in Unreal Engine 5 for modular gameplay architecture.
        </p>
      </FeatureContainer>

      <SectionHeader>Unity Gameplay Features:</SectionHeader>
      <FeatureList>
        {unityFeatures.map((feature, index) => (
          <FeatureItem key={index}>
            <FeatureTitle>{feature.feature}</FeatureTitle>
            <FeatureImage src={feature.image} alt={feature.feature} />
            <p>{feature.description}</p>
          </FeatureItem>
        ))}
      </FeatureList>

      <SectionHeader>Unreal Gameplay Systems:</SectionHeader>
      <FeatureList>
        {unrealFeatures.map((feature, index) => (
          <FeatureItem key={index}>
            <FeatureTitle>{feature.feature}</FeatureTitle>
            <FeatureImage src={feature.image} alt={feature.feature} />
            <p>{feature.description}</p>
          </FeatureItem>
        ))}
      </FeatureList>
    </Project>
  );
};

export default InterstellarDefenseEngineer;
