import React from 'react';
import styled from 'styled-components';
import { graphql, useStaticQuery } from "gatsby";
import Bubble from "../reusable/Bubble";
import E9 from "./projects/E9";
import ZeldaClone from "./projects/ZeldaClone";
import BO6 from "./projects/B06";
import MathCommand from "./projects/MathCommand";
import BiggestFishInThePond from "./projects/BiggestFishInThePond";
import HobbitSays from "./projects/HobbitSays";
import Arduino from "./projects/Arduino";
import GraphWars from "./projects/GraphWars";
import EcoSystemSimulator from "./projects/EcoSystemSimulator";
import KikisCantina from "./projects/KikisCantina";
import Portfolio from "./projects/Portfolio";
import MergyDergy from "./projects/MergyDergy";
import InterstellerDefenseEngineer from "./projects/InterstellerDefenseEngineer";
import GameEngine from "./projects/GameEngine";
import MyAssetShowcase from "./MyAssetShowcase";

const ProjectsSection: React.FC = () => {
  const data = useStaticQuery(graphql` query { site { siteMetadata { bannerLogo } } } `);

  if (!data) return <div>Failed to load site metadata</div>;

  return (
    <Bubble maxWidth={"auto"}>
      <SectionStyled id={"projects"}>
        <h2>Games/Projects</h2>
        <CategorySection>
          <h3>Featured</h3>
          <ProjectsGrid>
            <BO6/>
            <KikisCantina/>
            <E9/>
            <InterstellerDefenseEngineer/>
          </ProjectsGrid>
        </CategorySection>
        <CategorySection>
          <h3>3D Projects</h3>
          <ProjectsGrid>
            <EcoSystemSimulator/>
          </ProjectsGrid>
        </CategorySection>
        <CategorySection>
          <h3>2D Projects</h3>
          <ProjectsGrid>
            <GraphWars/>
            <GameEngine/>
            <MergyDergy/>
            <MathCommand/>
            <ZeldaClone/>
            <BiggestFishInThePond/>
            <HobbitSays/>
          </ProjectsGrid>
        </CategorySection>
        <CategorySection>
          <h3>Software/Non-game Projects</h3>
          <ProjectsGrid>
            <Portfolio/>
          </ProjectsGrid>
        </CategorySection>
        <CategorySection>
          <h3>Experiments</h3>
          <ProjectsGrid>
            <Arduino/>
          </ProjectsGrid>
        </CategorySection>
        {/*<CategorySection>*/}
        {/*  <h3>Visual & Audio Assets</h3>*/}
        {/*    <MyAssetShowcase />*/}
        {/*</CategorySection>*/}
      </SectionStyled>
    </Bubble>
  );
};

export default ProjectsSection;

export const SectionStyled = styled.section`
    padding: 1rem;

    h2 {
        color: red;
    }
`;

const CategorySection = styled.div`
    margin-bottom: 3rem; 

    h3 {
        color: #ffffff;
        text-shadow: 1px 1px 2px #000000;
        margin-bottom: 1rem;
    }
`;

const ProjectsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
`;
